59: export function GraphProvider({ children, fallback, onError }: GraphProviderProps) {
60:   const session = useSession();
61:   const [runtime, setRuntime] = useState<GraphRuntime | null>(null);
62:   const [error, setError] = useState<Error | null>(null);
63: 
64:   useEffect(() => {
65:     if (!session) return;
66: 
67:     let cancelled = false;
68:     let opened: PGlite | null = null;
69: 
70:     void (async () => {
71:       try {
72:         // In-memory for now. A persisted store (idb://) survives reloads and
73:         // is the point of local-first — but it also means PHI at rest in the
74:         // browser, which is a decision this phase has not taken. Deliberately
75:         // ephemeral until it is.
76:         const pglite = new PGlite();
77:         opened = pglite;
78:         await pglite.exec(PGLITE_SCHEMA_SQL);
79: 
80:         const storage = await createPGlitePersistenceAdapter(pglite);
81:         const store = createGraphStore();
82:         startLocalFirstGraph({ storage, store, key: `aso:${session.practiceId}` });
83: 
84:         if (cancelled) {
85:           void pglite.close();
86:           return;
87:         }
88:         setRuntime({ store, pglite });
89:       } catch (cause) {
90:         if (!cancelled) {
91:           setError(cause instanceof Error ? cause : new Error(String(cause)));
92:         }
93:       }
94:     })();
95: 
96:     return () => {
97:       cancelled = true;
98:       void opened?.close();
99:     };
100:   }, [session]);
101: 
102:   if (!session) return <>{fallback ?? null}</>;
103:   if (error) return <>{onError?.(error) ?? null}</>;
104:   if (!runtime) return <>{fallback ?? null}</>;
105: 
106:   return (
107:     <LocalStoreContext value={runtime.pglite}>
108:       <GraphStoreProvider store={runtime.store}>{children}</GraphStoreProvider>
109:     </LocalStoreContext>
110:   );

190: function adaptShapeStream(
191:   stream: ShapeStream<Record<string, unknown>>,
192: ): GraphShapeStream {
193:   const adapted = {
194:     ...stream,
195:     subscribe(
196:       onMsg: (
197:         msgs: {
198:           headers: { operation: "insert" | "update" | "delete" };
199:           offset: string;
200:           value: Record<string, unknown>;
201:           key: string;
202:         }[],
203:       ) => void,
204:       onErr?: (e: Error) => void,
205:     ) {
206:       return stream.subscribe((messages) => {
207:         const changes = messages.flatMap((m, i) =>
208:           "key" in m && "value" in m
209:             ? [
210:                 {
211:                   key: m.key,
212:                   value: m.value,
213:                   headers: {
214:                     operation: m.headers.operation as "insert" | "update" | "delete",
215:                   },
216:                   // Synthetic. The graph never reads it; the type requires it.
217:                   offset: `${Date.now()}_${i}`,
218:                 },
219:               ]
220:             : [],
221:         );
222:         if (changes.length > 0) onMsg(changes);
223:       }, onErr);
224:     },

27: export function useEvidenceTimeline(caseId: string): UseEvidenceTimeline {
28:   const db = useLocalStore();
29:   const [entries, setEntries] = useState<readonly TimelineEntry[]>([]);
30:   const [loading, setLoading] = useState(true);
31:   const [error, setError] = useState<string | null>(null);
32:   const [refusal, setRefusal] = useState<string | null>(null);
33: 
34:   useEffect(() => {
35:     if (!db) return;
36: 
37:     let live = true;
38:     setLoading(true);
39:     readTimeline(db, caseId)
40:       .then((rows) => {
41:         if (!live) return;
42:         setEntries(rows);
43:         setError(null);
44:       })
45:       .catch((e: unknown) => {
46:         // An empty list and a failed read look identical on screen, and one of
47:         // them means "no evidence recorded" while the other means "we do not
48:         // know". Never let a failure render as the former.
49:         if (live) setError(e instanceof Error ? e.message : String(e));
50:       })
51:       .finally(() => {
52:         if (live) setLoading(false);
53:       });
54: 
55:     return () => {
56:       live = false;
57:     };
58:   }, [db, caseId]);

