176: pub fn validate_subject_provider(
177:     provider: &crate::config::types::AuthProviderConfig,
178: ) -> Result<(), String> {
179:     use crate::config::types::AuthProviderConfig as P;
180:     match provider {
181:         P::Jwt(cfg) => {
182:             if cfg.issuer.is_none() {
183:                 return Err(
184:                     "token-exchange subject_token_provider (jwt) must pin `issuer` \
185:                      (and ideally `audience`); an unpinned JWT verifier trusts any \
186:                      issuer in its JWKS"
187:                         .to_string(),
188:                 );
189:             }
190:             Ok(())
191:         }
192:         // The MCP provider already fails closed at build time without
193:         // issuer+audience (RFC 8707), so it is a safe subject-token verifier.
194:         P::Mcp(_) => Ok(()),
195:         P::Kratos(_) | P::ApiKey(_) | P::Anonymous(_) => Err(
196:             "token-exchange subject_token_provider must be a JWKS-backed `jwt` or \
197:              `mcp` provider that cryptographically verifies the subject_token; \
198:              anonymous/api_key/kratos providers would fail open"
199:                 .to_string(),
200:         ),
201:     }

