46: impl Authenticator for KratosAuthenticator {
47:     async fn authenticate(&self, parts: &Parts) -> Result<AuthResult, AuthError> {
48:         let mut req = self.client.get(format!(
49:             "{}/sessions/whoami",
50:             self.config.base_url.trim_end_matches('/')
51:         ));
52: 
53:         // Forward session cookie if present
54:         if self.config.forward_cookies {
55:             if let Some(cookie_header) = parts.headers.get(COOKIE) {
56:                 req = req.header(COOKIE, cookie_header);
57:             }
58:         }
59: 
60:         // Forward Authorization header if present
61:         if let Some(auth_header) = parts.headers.get(AUTHORIZATION) {
62:             req = req.header(AUTHORIZATION, auth_header);
63:         }
64: 
65:         let response = req.send().await.map_err(|e| {
66:             tracing::warn!(error = %e, "Kratos request failed");
67:             AuthError::ProviderError(format!("Kratos unreachable: {e}"))
68:         })?;
69: 
70:         let status = response.status();
71: 
72:         if status == http::StatusCode::UNAUTHORIZED || status == http::StatusCode::FORBIDDEN {
73:             return Err(AuthError::Unauthorized(
74:                 "invalid or expired Kratos session".to_string(),
75:             ));
76:         }
77: 
78:         if !status.is_success() {
79:             return Err(AuthError::ProviderError(format!(
80:                 "Kratos returned status {status}"
81:             )));
82:         }
83: 
84:         let session: KratosSession = response.json().await.map_err(|e| {
85:             AuthError::ProviderError(format!("failed to parse Kratos response: {e}"))
86:         })?;
87: 
88:         if session.active == Some(false) {
89:             return Err(AuthError::Unauthorized(
90:                 "Kratos session is inactive".to_string(),
91:             ));
92:         }
93: 
94:         let kratos_id = session.identity.ok_or_else(|| {
95:             AuthError::ProviderError("Kratos response missing identity".to_string())
96:         })?;
97: 
98:         // Kratos `metadata_public` is admin- and (in some deployments)
99:         // self-service-writable, so it is UNTRUSTED for principal-kind: strip any
100:         // `flint_kind` a Kratos identity might carry, otherwise a human could set
101:         // `flint_kind: service` and escalate to a non-human principal.
102:         let mut metadata_public = kratos_id.metadata_public.unwrap_or(Value::Null);

