125: export async function persistGraphToStorage(opts: PersistGraphToStorageOptions) {
126:   const storeApi = opts.store ?? graphStore;
127:   const payload: GraphSnapshotPayload = {
128:     version: 1,
129:     snapshot: cloneGraphSnapshot(storeApi),
130:     pendingActions: opts.pendingActions ?? Array.from(pendingActions.values()),
131:   };
132:   const json = JSON.stringify(payload);
133:   await opts.storage.set(opts.key, json);
134:   const persistedAt = new Date().toISOString();
135:   graphSyncStatusStore.getState().setStatus({
136:     lastPersistedAt: persistedAt,
137:     storageKey: opts.key,
138:     pendingActions: payload.pendingActions.length,
139:   });
140:   return {
141:     ok: true as const,
142:     key: opts.key,
143:     bytes: json.length,
144:     persistedAt,
145:   };
146: }
