148: export async function hydrateGraphFromStorage(opts: HydrateGraphFromStorageOptions) {
149:   const storeApi = opts.store ?? graphStore;
150:   const raw = await opts.storage.get(opts.key);
151:   if (!raw) {
152:     return {
153:       ok: false as const,
154:       key: opts.key,
155:       hydratedAt: null,
156:       entityCounts: {},
157:       error: "No persisted graph snapshot found",
158:     };
159:   }
160: 
161:   try {
162:     const parsed = JSON.parse(raw) as GraphSnapshotPayload;
163:     storeApi.setState(parsed.snapshot as Partial<ReturnType<typeof graphStore.getState>>);
164:     pendingActions.clear();
165:     for (const action of parsed.pendingActions ?? []) pendingActions.set(action.id, action);
166:     const hydratedAt = new Date().toISOString();
167:     graphSyncStatusStore.getState().setStatus({
168:       lastHydratedAt: hydratedAt,
169:       storageKey: opts.key,
170:       pendingActions: pendingActions.size,
171:       error: null,
172:     });
173:     return {
174:       ok: true as const,
175:       key: opts.key,
176:       hydratedAt,
177:       entityCounts: Object.fromEntries(
178:         Object.entries(parsed.snapshot.entities).map(([type, entities]) => [type, Object.keys(entities).length]),
179:       ),
180:       pendingActions: Array.from(pendingActions.values()),
181:     };
182:   } catch (error) {
183:     const message = error instanceof Error ? error.message : String(error);
184:     graphSyncStatusStore.getState().setStatus({
185:       phase: "error",
186:       error: message,
187:       storageKey: opts.key,
188:     });
189:     return {
190:       ok: false as const,
191:       key: opts.key,
192:       hydratedAt: null,
193:       entityCounts: {},
194:       error: message,
195:     };
196:   }
197: }
