199: export function startLocalFirstGraph(opts: StartLocalFirstGraphOptions): LocalFirstGraphRuntime {
200:   const storeApi = opts.store ?? graphStore;
201:   const key = opts.key ?? DEFAULT_STORAGE_KEY;
202:   const persistDebounceMs = opts.persistDebounceMs ?? 50;
203:   const statusStore = graphSyncStatusStore.getState();
204:   statusStore.setStatus({
205:     phase: "hydrating",
206:     storageKey: key,
207:     isOnline: opts.onlineSource?.getIsOnline() ?? getDefaultOnlineSource().getIsOnline(),
208:     isSynced: pendingActions.size === 0,
209:     error: null,
210:   });
211: 
212:   let persistTimer: ReturnType<typeof setTimeout> | null = null;
213:   const schedulePersist = () => {
214:     if (persistTimer) clearTimeout(persistTimer);
215:     persistTimer = setTimeout(() => {
216:       void persistGraphToStorage({ storage: opts.storage, key, store: storeApi });
217:     }, persistDebounceMs);
218:   };
219: 
220:   const graphUnsub = storeApi.subscribe(() => {
221:     schedulePersist();
222:   });
223: 
224:   const actionUnsub = subscribeGraphActionEvents((event) => {
225:     if (event.type === "enqueued") pendingActions.set(event.record.id, event.record);
226:     if (event.type === "settled") pendingActions.delete(event.record.id);
227:     graphSyncStatusStore.getState().setStatus({
228:       pendingActions: pendingActions.size,
229:       isSynced: pendingActions.size === 0,
230:     });
231:     schedulePersist();
232:   });
233: 
234:   const onlineSource = opts.onlineSource ?? getDefaultOnlineSource();
235:   const onlineUnsub = onlineSource.subscribe((online) => {
236:     graphSyncStatusStore.getState().setStatus({
237:       isOnline: online,
238:       phase: online ? "ready" : "offline",
239:     });
240:   });
241: 
242:   const ready = (async () => {
243:     const hydrated = await hydrateGraphFromStorage({ storage: opts.storage, key, store: storeApi });
244:     if (opts.replayPendingActions && hydrated.ok && pendingActions.size > 0) {
245:       graphSyncStatusStore.getState().setStatus({
246:         phase: "syncing",
247:         isSynced: false,
248:       });
249:       const policy = resolveRetryPolicy(opts.retryPolicy);
250:       for (const action of Array.from(pendingActions.values())) {
251:         await replayActionWithRetry(action, policy, storeApi);
252:         // Whether it succeeded or was poisoned, remove from pending — the
253:         // poison handler (if any) owns escalation from here.
254:         pendingActions.delete(action.id);
255:       }
256:       await persistGraphToStorage({ storage: opts.storage, key, store: storeApi });
257:     }
258: 
259:     const online = onlineSource.getIsOnline();
260:     graphSyncStatusStore.getState().setStatus({
261:       phase: online ? "ready" : "offline",
262:       isOnline: online,
263:       isSynced: pendingActions.size === 0,
264:       pendingActions: pendingActions.size,
265:     });
266:   })();
267: 
268:   return {
269:     ready,
270:     dispose() {
271:       graphUnsub();
272:       actionUnsub();
273:       onlineUnsub();
274:       if (persistTimer) clearTimeout(persistTimer);
275:     },
276:     async persistNow() {
277:       await persistGraphToStorage({ storage: opts.storage, key, store: storeApi });
278:     },
279:     hydrate() {
280:       return hydrateGraphFromStorage({ storage: opts.storage, key, store: storeApi });
281:     },
282:     getStatus() {
283:       return graphSyncStatusStore.getState().status;
